const rows = $('Load Tournaments').all().map(i => i.json).filter(r => r && r._set);
const b2 = $('Authorize B2').isExecuted ? $('Authorize B2').first().json : {};
const tokenOf = node => { try { return $(node).isExecuted ? $(node).first().json.authorizationToken : null; } catch { return null; } };
const dl = b2?.apiInfo?.storageApi?.downloadUrl;
const signed = key => {
  const t = key && tokenOf(key.startsWith('tournament_assets/') ? 'Assets Link' : 'Logo Link');
  return key && dl && t ? `${dl}/file/mypaltan-profile-photos/${key.split('/').map(encodeURIComponent).join('/')}?Authorization=${t}` : null;
};
const parseTags = t => { if (Array.isArray(t)) return t; try { return JSON.parse(t || '[]'); } catch { return []; } };
// Approved public tournaments first (they can be joined now), then the featured leagues.
const tournaments = rows.filter(r => r._set === 'tournament').map(r => ({
  slug: r.slug || null, code: r.code || null, name: r.name, sport: r.sport, logo_url: signed(r.logo_key) || r.logo_url || null, start_date: r.start_date || null,
  area: r.area || null, city: r.city, tags: parseTags(r.tags), status: r.status,
}));
const banners = rows.filter(r => r._set === 'banner').map(r => ({
  id: r.id, title: r.title, subtitle: r.subtitle || null, badge: r.badge || null, image_url: signed(r.image_key) || r.image_url || null,
  theme: r.theme, cta_label: r.cta_label || null, link_type: r.link_type, link_value: r.link_value || null,
}));
const unreadRow = rows.find(r => r._set === 'unread');

return [{ json: { status: 200, body: { success: true, featured_tournaments: tournaments } } }];
